{
  "version": 1,
  "hooks": {
    "beforeSubmitPrompt": [
      {
        "command": "/Users/riza/.superset/hooks/cursor-hook.sh Start"
      }
    ],
    "stop": [
      {
        "command": "/Users/riza/.superset/hooks/cursor-hook.sh Stop"
      },
      {
        "command": "./hooks/elixir-phoenix/adapter.sh stop"
      }
    ],
    "beforeShellExecution": [
      {
        "command": "/Users/riza/.superset/hooks/cursor-hook.sh PermissionRequest"
      },
      {
        "command": "./hooks/elixir-phoenix/adapter.sh beforeShellExecution"
      }
    ],
    "beforeMCPExecution": [
      {
        "command": "/Users/riza/.superset/hooks/cursor-hook.sh PermissionRequest"
      }
    ],
    "preToolUse": [
      {
        "command": "./hooks/rtk-rewrite.sh",
        "matcher": "Shell"
      },
      {
        "command": "./hooks/elixir-phoenix/adapter.sh preToolUse",
        "matcher": "Write|StrReplace|EditNotebook"
      }
    ],
    "postToolUse": [
      {
        "command": "./hooks/elixir-phoenix/adapter.sh postToolUse",
        "matcher": "Write|StrReplace|EditNotebook"
      }
    ],
    "sessionStart": [
      {
        "command": "./hooks/elixir-phoenix/adapter.sh sessionStart"
      }
    ],
    "preCompact": [
      {
        "command": "./hooks/elixir-phoenix/adapter.sh preCompact"
      }
    ]
  }
}
